INSERT INTO _exercise_staging (id, name, category, equipment, primary_muscles, secondary_muscles, description, video_code, video_filename, gender, is_custom, created_at, steps_to_perform, movement_pattern, force_type, movement_type, laterality, plane_of_motion, difficulty_level, complexity_score, strength_rating, hypertrophy_rating, power_rating, endurance_rating, body_position, bench_angle, grip_type, grip_width, optimal_rep_range_min, optimal_rep_range_max, placement_in_workout, fatigability, popularity_score, home_gym_friendly, instructions, workout_type, practicality_score, fat_loss_rating, general_fitness_rating, is_compound, supersetable, exercise_family, base_exercise_name, complementary_families, is_equipment_primary, equipment_category, duration_based, recommended_sets, rest_seconds, muscles_worked_count, priority_build_muscle, priority_get_lean, priority_home, priority_gym) VALUES
('b35ca8fd-465e-4d77-a4c9-401fe48ea2e6', 'Reverse Sliding Leg Curl On Floor (Towel)', 'Legs', 'Towel', '{"Hamstrings"}'::text[], '{"Glutes"}'::text[], 'This curling movement works your hamstrings for balanced leg development. The calves assist throughout the movement, making this a well-rounded exercise. Lower body strength improves everything from walking to heavy compound lifts.', '48971201', '48971201-Reverse-Sliding-Leg-Curl-on-Floor-with-Towel_Thigh.mp4', 'male', FALSE, '2025-12-03 23:26:29.61214+00', '1. Position yourself on the floor for Reverse Sliding Leg Curl On Floor With Towel. 2. Curl your heels toward your glutes by bending at the knees. 3. Squeeze your hamstrings at peak contraction. 4. Extend legs back out with control. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 75, 7, 8, TRUE, TRUE, 'leg_curl', 'Reverse Sliding Leg Curl On Floor With Towel', 'romanian_deadlift, hip_thrust', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('b3611566-2698-4a5d-9c83-8d56ee996dad', 'Hip Raise (Bent Knee)', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Hip Raise (bent Knee), focusing on your abs. This bodyweight exercise requires no equipment and can be done anywhere. Core strength is foundational for athletic performance and injury prevention.', '4841201', '04841201-Hip-Raise-(bent-knee)_waist.mp4', 'male', FALSE, '2025-12-03 23:26:28.260518+00', '1. Raise the weight in the prescribed direction for Hip Raise. 2. Lower with control, maintaining tension throughout. 3. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'glute_exercise', 'Hip Raise', 'hip_thrust, lunge, squat', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('b365b5c7-c714-4805-8f52-780599f4bb04', 'Seated Twist (Stability Ball, Barbell)', 'Core', 'Barbell, Stability Ball, Flat Bench', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'Work your side abdominals with this twisting exercise that strengthens your obliques. You''ll also feel your abs working to support the movement. The seated position helps isolate the target muscles by removing momentum. Using a barbell provides stability for progressive overload. A strong core improves posture, protects your spine, and enhances all other lifts.', '931201', '00931201-Barbell-Seated-Twist-(on-stability-ball)_Waist.mp4', 'female', FALSE, '2025-12-03 23:26:31.133197+00', '1. Grip a barbell with hands at the appropriate width for Barbell Seated Twist. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Rotate your torso through the movement pattern for Barbell Seated Twist. 4. Control the rotation in both directions—avoid using momentum. 5. Repeat for the prescribed number of repetitions. Focus on squeezing the target muscle at peak contraction. An effective movement for your core routine.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 48, 5, 7, FALSE, TRUE, 'russian_twist', 'Seated Twist', 'plank, crunch, leg_raise', FALSE, 'barbell', FALSE, 3, 60, 2, 95, 80, 65, 95),
('b36aa16a-3c30-4db9-a7a5-1a71a1540b7d', 'Opposite Superman Lift And Row - Alternating', 'Back', 'Bodyweight', '{"Lower Back"}'::text[], '{"Glutes","Upper Back"}'::text[], 'The Alternate Opposite Superman Lift And Row strengthens your lower back muscles through a controlled rowing motion. Secondary activation of your glutes provides additional muscle engagement. No equipment needed—your body provides all the resistance. Building core stability helps with everything from heavy deadlifts to daily activities.', '96241201', '96241201-Alternate-Opposite-Superman-Lift-and-Row-(female)_.mp4', 'female', FALSE, '2025-12-03 23:26:30.412523+00', '1. Pull the weight toward your torso, leading with your elbow(s). 2. Squeeze your shoulder blades together at the peak contraction. 3. Extend back out with control, feeling the stretch in your back. 4. Alternate between sides/arms/legs with each repetition. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'back_extension', 'Opposite Superman Lift And Row - Alternating', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('b36cf345-d6eb-4d39-b694-992532970f1d', 'Single Arm Lateral High Row (Machine)', 'Back', 'Row Machine', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'The Lever One Arm Lateral High Row is a rowing exercise that builds thickness in your upper back. The biceps, rear delts assist throughout the movement, making this a well-rounded exercise. Machine exercises are great for isolating muscles and training to failure safely. Back development is crucial for pulling strength and overall upper body function.', '74071201', '74071201-Lever-One-Arm-Lateral-High-Row-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:34.724336+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever One Arm Lateral High Row. 2. Pull the weight toward your torso, leading with your elbow(s). 3. Squeeze your shoulder blades together at the peak contraction. 4. Extend back out with control, feeling the stretch in your back. 5. Complete all reps on one side, then switch to the other side. 6. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, FALSE, NULL, 'Strength', 73, 7, 9, TRUE, FALSE, 'cable_row', 'Lever Single Arm Lateral High Row', 'bent_over_row, lat_pulldown, bicep_curl', FALSE, 'machine', FALSE, 4, 120, 4, 80, 75, 20, 88),
('b3707525-2d85-4568-a97b-1b12fb5e52ea', 'SZ Bar Curl - Close Grip (Cable)', 'Arms', 'Cables', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'The Cable SZ Bar Close Grip Curl is a curling exercise that isolates your biceps. Your forearms work as secondary movers, adding to the training stimulus. Cable resistance creates smooth, continuous muscle engagement. Dedicated arm training builds both strength and muscular definition.', '59221201', '59221201-Cable-SZ-bar-Close-Grip-Curl_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:22.938497+00', '1. Adjust the cable machine to the correct height and attachment for Cable SZ Bar Close Grip Curl. 2. Use a close/narrow grip (hands closer than shoulder-width). 3. Keep your elbows in a fixed position throughout the movement. 4. Curl the weight up by contracting your biceps, squeezing at the top. 5. Lower with control, resisting the weight on the way down. 6. Repeat for the prescribed number of repetitions.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 80, 5, 7, FALSE, TRUE, 'bicep_curl', 'SZ Bar Curl - Close Grip', 'SZ Bar Curl - Close Grip', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('b3776bd4-a98b-4b94-adb0-8cfa5cdd5df4', 'Seated In Out Leg Raise On Floor', 'Core', 'Bodyweight', '{"Lower Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This raising exercise engages your abs for improved core stability and strength. You''ll also feel your hip flexors working to support the movement. The seated position helps isolate the target muscles by removing momentum. Core strength is foundational for athletic performance and injury prevention.', '42741201', '42741201-Seated-In-Out-Leg-Raise-on-Floor-(female)_Waist.mp4', 'female', FALSE, '2025-12-03 23:26:36.717157+00', '1. Position yourself on the floor for Seated In Out Leg Raise On Floor. 2. Sit on the floor with your legs positioned as required. 3. Keeping legs mostly straight, raise them toward the ceiling. 4. Lower with control, stopping just before touching down. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 67, 5, 7, FALSE, TRUE, 'leg_raise', 'Seated In Out Leg Raise On Floor', 'crunch, plank, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('b3798bfa-e686-488e-bfb7-dd6b84a67e93', 'Sled 45 Degrees Wide Stance Leg Press (Machine)', 'Legs', 'Leg Press Machine', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target the front of your thighs with this pressing exercise for quad development. Your glutes work as secondary movers, adding to the training stimulus. Lower body strength improves everything from walking to heavy compound lifts.', '36171201', '36171201-Sled-45-degrees-Wide-Stance-Leg-Press-(female)_Thighs.mp4', 'female', FALSE, '2025-12-03 23:26:37.99429+00', '1. Use a wide grip (wider than shoulder-width) for this variation. 2. Position your feet on the platform and release the safety. 3. Lower the weight by bending your knees, then press back up powerfully. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, FALSE, NULL, 'Strength', 80, 7, 9, TRUE, FALSE, 'leg_press', 'Sled 45 Degrees Wide Stance Leg Press', 'squat, hack_squat, lunge', TRUE, 'machine', FALSE, 4, 120, 4, 80, 75, 20, 88),
('b38602a9-ba13-4432-830d-b52096d45d8e', 'Ring Reverse Curl (Gymnastic Rings) - Alternating', 'Arms', 'Gymnastic Rings', '{"Forearms"}'::text[], '{"Biceps"}'::text[], 'The Ring Alternate Reverse Curl is a lower body curling exercise that targets your forearms. Your biceps work as secondary movers, adding to the training stimulus. Leg training boosts metabolism and builds functional, real-world strength.', '77101201', '77101201-Ring-Alternate-Reverse-Curl_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:29.837118+00', '1. Keep your elbows in a fixed position throughout the movement. 2. Curl the weight up by contracting your biceps, squeezing at the top. 3. Lower with control, resisting the weight on the way down. 4. Repeat for the prescribed number of repetitions. Engage your stabilizer muscles for better control.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 58, 5, 7, FALSE, TRUE, 'general_exercise', 'Ring Reverse Curl - Alternating', 'hammer_curl, wrist_curl, bicep_curl', FALSE, 'gymnastic_rings', FALSE, 3, 60, 2, 68, 85, 85, 70),
('b38734d5-d0c2-4deb-9b51-b59016059395', 'Crunch (Stability Ball, Medicine Ball)', 'Core', 'Medicine Ball, Stability Ball', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Medicine Ball Crunch On Stability Ball, focusing on your abs. Secondary activation of your hip flexors provides additional muscle engagement. The stability ball adds an instability challenge that activates more stabilizer muscles. Core strength is foundational for athletic performance and injury prevention.', '90101201', '90101201-Medicine-Ball-Crunch-on-Stability-Ball-(male)_Wais.mp4', 'male', FALSE, '2025-12-03 23:26:27.263406+00', '1. Hold a medicine ball at the appropriate position for Medicine Ball Crunch On Stability Ball. 2. Curl your shoulders off the floor by contracting your abs. 3. Don''t pull on your neck—focus on the abdominal contraction. 4. Lower with control, maintaining some tension. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 62, 5, 7, FALSE, TRUE, 'crunch', 'Medicine Ball Crunch On Stability Ball', 'leg_raise, plank, russian_twist, v_up', TRUE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('b398b73b-70f5-4f90-9668-8b1ceb87221e', 'Side Lying T Thigh Raise Hold', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Side Lying T Thigh Raise Hold is a lower body raising exercise that targets your core. Performing this lying down removes momentum for stricter form. A versatile bodyweight movement perfect for home or gym training. Strong legs are the foundation for athletic performance and functional fitness.', '78001201', '78001201-Side-Lying-T-Thigh-Raise-Hold-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:37.179953+00', '1. Lie on your side with your body aligned. 2. Raise your arms out to the sides until parallel to the floor. 3. Lower with control, maintaining tension throughout. 4. Hold the position for the prescribed time, maintaining tension.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 65, 5, 7, FALSE, TRUE, 'leg_exercise', 'Side Lying T Thigh Raise Hold', 'shoulder_press, front_raise, rear_delt_fly, upright_row', FALSE, 'bodyweight', TRUE, 3, 60, 2, 70, 88, 95, 65),
('b3c0fa98-2603-46ed-95cc-7152ed1d61d0', 'Single Arm Twisting Seated Row (Cable)', 'Back', 'Cables', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'The Cable One Arm Twisting Seated Row is a rowing exercise that builds thickness in your upper back. The biceps, lats assist throughout the movement, making this a well-rounded exercise. Being seated provides stability, allowing you to focus on the working muscles. Cable resistance creates smooth, continuous muscle engagement. A strong back improves posture, prevents injury, and balances pressing movements.', '35971201', '35971201-Cable-One-Arm-Twisting-Seated-Row-(female)_Back.mp4', 'female', FALSE, '2025-12-03 23:26:31.931873+00', '1. Adjust the cable machine to the correct height and attachment for Cable One Arm Twisting Seated Row. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Complete all reps on one side, then switch to the other side. 7. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 79, 7, 8, TRUE, TRUE, 'cable_row', 'Single Arm Twisting Seated Row', 'bent_over_row, lat_pulldown, face_pull', TRUE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('b3c2168d-24ae-43c6-bda0-da28167a9873', 'V Feet Raise - Alternating', 'Shoulders', 'Bodyweight', '{"Rear Delts"}'::text[], '{"Upper Back","Rotator Cuff"}'::text[], 'Build leg strength with this raising movement focusing on your hip abductors. You''ll also feel your glutes working to support the movement. A versatile bodyweight movement perfect for home or gym training. Strong legs are the foundation for athletic performance and functional fitness.', '89331201', '89331201-Alternate-V-Feet-Raises-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:30.412523+00', '1. Raise the weight in the prescribed direction for Alternate V Feet Raises. 2. Lower with control, maintaining tension throughout. 3. Alternate between sides/arms/legs with each repetition. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'lateral_raise', 'V Feet Raise - Alternating', 'shoulder_press, front_raise, rear_delt', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('b3d85cb4-b26c-4b20-93b1-fa3d55e13683', 'Inline Skating', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'A challenging plyometric exercise, the Inline Skating builds reactive power and improves conditioning. No equipment needed—your body provides all the resistance. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '71751201', '71751201-Inline-Skating-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:34.073704+00', '1. Set up in the starting position for Inline Skating. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'skater', 'Inline Skating', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('b3e23e8e-38dd-489c-9bf1-64a55c00f174', 'Seated Bent Knee Abduction (Resistance Band)', 'Legs', 'Resistance Band', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Resistance Band Seated Bent Knee Abduction is a lower body movement exercise that targets your hip abductors. The glutes assist throughout the movement, making this a well-rounded exercise. Being seated provides stability, allowing you to focus on the working muscles. Resistance bands provide accommodating resistance that increases through the range of motion. Lower body strength improves everything from walking to heavy compound lifts.', '72001201', '72001201-Resistance-Band-Seated-Bent-Knee-Abduction-(female.mp4', 'female', FALSE, '2025-12-03 23:26:36.128549+00', '1. Secure the resistance band appropriately for Resistance Band Seated Bent Knee Abduction. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 57, 7, 8, TRUE, TRUE, 'hip_abduction', 'Seated Bent Knee Abduction', 'squat, leg_extension, lunge', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('b3ebdc9c-645b-4308-853f-7e8eb4e397b3', 'Skull Crusher (Barbell)', 'Arms', 'Barbell, Flat Bench', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'This movement movement isolates your triceps for improved arm development. The barbell allows you to handle heavier loads for maximum strength gains. Dedicated arm training builds both strength and muscular definition.', '103801201', '103801201-Barbell-Skull-Crusher-(VERSION-2)_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:29.971345+00', '1. Grip a barbell with hands at the appropriate width for Barbell Skull Crusher. 2. Set up in the starting position for Barbell Skull Crusher. 3. Execute the movement with proper form, focusing on your triceps. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 92, 7, 8, TRUE, TRUE, 'tricep_extension', 'Skull Crusher', 'tricep_pushdown, close_grip_bench', TRUE, 'barbell', FALSE, 3, 90, 4, 95, 80, 65, 95),
('b3ec47aa-89ec-4d76-8416-3d078916dc29', 'Single Leg Support Balance', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Use this stretch to open up your full body area and enhance overall flexibility. Regular stretching improves flexibility, reduces injury risk, and aids recovery. Control the negative portion for maximum muscle engagement.', '85301201', '85301201-Single-Leg-Support-Balance-(male)_Stretching_.mp4', 'male', FALSE, '2025-12-03 23:26:29.36063+00', '1. Move into the stretch position for Single Leg Support Balance. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. 4. Switch sides and repeat for equal time. 5. Complete all reps on one side, then switch to the other side.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 45, 7, 8, TRUE, TRUE, 'balance', 'Single Leg Support Balance', 'squat, lunge, leg_press', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('b3f535d7-cc50-4d03-9a69-43752a646919', 'Leg Over Knee Glute Bridge (left)', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'Build stronger glutes with this bridging movement focused on hip extension. Your hamstrings work as secondary movers, adding to the training stimulus. No equipment needed—your body provides all the resistance. Leg training boosts metabolism and builds functional, real-world strength. Works well as both a primary exercise or accessory movement.', '73251201', '73251201-Leg-Over-Knee-Glute-Bridge-(left)-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:34.603963+00', '1. Drive through your heels to lift your hips toward the ceiling. 2. Squeeze your glutes hard at the top of the movement. 3. Lower your hips back down with control. 4. Repeat for the prescribed number of repetitions. Don''t rush—quality over quantity.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'glute_bridge', 'Leg Over Knee Glute Bridge', 'hip_thrust, romanian_deadlift', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('b3fe6ab2-78b3-451b-b27f-f2b4afe94c49', 'Lying Legs Triangle Drop', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build leg strength with this movement movement focusing on your core. The lying position provides back support and helps isolate the target muscles. A versatile bodyweight movement perfect for home or gym training. Lower body strength improves everything from walking to heavy compound lifts. Quality repetitions are more important than quantity.', '73921201', '73921201-Lying-Legs-Triangle-Drop-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:27.384461+00', '1. Lie down in the appropriate position for Lying Legs Triangle Drop. 2. Set up in the starting position for Lying Legs Triangle Drop. 3. Execute the movement with proper form, focusing on your core. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'yoga', 'Lying Legs Triangle Drop', 'squat, lunge, leg_press', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('b40f8c33-32ff-43f5-9b22-3c3c2a487ee6', 'Seated Fist Pulse', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Seated Fist Pulse is an arm movement exercise targeting your core. Being seated provides stability, allowing you to focus on the working muscles. Dedicated arm training builds both strength and muscular definition.', '89421201', '89421201-Seated-Fist-Pulse-(male)_Forearms_.mp4', 'male', FALSE, '2025-12-03 23:26:27.805708+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. At the bottom or top, pulse up and down in small movements before completing the rep. 3. Complete all reps with control before resting. Keep the movement smooth and controlled.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'pulse', 'Seated Fist Pulse', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('b41128d1-db7c-4fe9-abe1-bc386fa8c37a', 'Low Lunge', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Low Lunge provides a deep stretch for your quads, ideal for recovery and mobility work. You''ll also feel your glutes, hamstrings working to support the movement. Include this in your routine for better mobility and reduced muscle tension.', '58931201', '58931201-Low-Lunge-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:35.010404+00', '1. Step forward into a lunge until both knees are at about 90 degrees. 2. Push through your front/working leg to return to the starting position. 3. Move into the stretch position for Low Lunge. 4. Ease into the stretch until you feel gentle tension (not pain). 5. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'lunge', 'Low Lunge', 'split_squat, step_up, squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('b41419ff-8704-429f-9941-cd235bccf76d', 'Knee Thrust Floor Tap', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'A challenging plyometric exercise, the Knee Thrust Floor Tap builds reactive power and improves conditioning. This bodyweight exercise requires no equipment and can be done anywhere. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '68931201', '68931201-Knee-Thrust-Floor-Tap-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:34.322534+00', '1. Position yourself on the floor for Knee Thrust Floor Tap. 2. Drive through your heels to lift your hips toward the ceiling. 3. Squeeze your glutes hard at the top of the movement. 4. Lower your hips back down with control. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 45, 7, 8, TRUE, TRUE, 'knee_drive', 'Knee Thrust Floor Tap', 'butt_kicks, jumping_jack, mountain_climber', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('b42f3e80-b1c4-4a1f-a520-4b8add59bad8', 'Seated Twist On Stability Ball (Barbell)', 'Core', 'Barbell, Stability Ball, Flat Bench', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'This twisting movement focuses on your obliques for a complete core workout. Your abs work as secondary movers, adding to the training stimulus. The seated position helps isolate the target muscles by removing momentum. The barbell allows you to handle heavier loads for maximum strength gains. Core strength is foundational for athletic performance and injury prevention.', '69891201', '69891201-Barbell-Seated-Twist-(on-stability-ball)-(male)_Wa.mp4', 'male', FALSE, '2025-12-03 23:26:26.808474+00', '1. Grip a barbell with hands at the appropriate width for Barbell Seated Twist. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Rotate your torso through the movement pattern for Barbell Seated Twist. 4. Control the rotation in both directions—avoid using momentum. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 48, 5, 7, FALSE, TRUE, 'russian_twist', 'Seated Twist', 'plank, crunch, leg_raise', FALSE, 'barbell', FALSE, 3, 60, 2, 95, 80, 65, 95),
('b442ad15-b32d-476d-a69b-eff552b8cec9', 'Bent Over Low Row (Machine)', 'Back', 'Row Machine', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'Target your rhomboids and mid-traps with this rowing movement. Your biceps, rear delts work as secondary movers, adding to the training stimulus. Bending over allows gravity to provide resistance in a different plane. The machine guides your movement path for safer, more controlled repetitions. Back development is crucial for pulling strength and overall upper body function.', '64951201', '64951201-Lever-Bent-Over-Low-Row-(male)_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:28.397686+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Bent Over Low Row. 2. Hinge at your hips, pushing them back while keeping your back flat. 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, FALSE, NULL, 'Strength', 78, 7, 9, TRUE, FALSE, 'cable_row', 'Lever Bent Over Low Row', 'lat_pulldown, pull_up, bicep_curl, face_pull, seated_row', FALSE, 'machine', FALSE, 4, 120, 4, 80, 75, 20, 88),
('b44ce5dd-f859-4707-b9b3-83b3b593d8de', 'Quadruped Hip Rotation', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Develop your posterior chain with this rotation movement that emphasizes the glutes. No equipment needed—your body provides all the resistance. Strong legs are the foundation for athletic performance and functional fitness.', '100281201', '100281201-Quadruped-Hip-Rotation-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:35.936279+00', '1. Rotate your torso through the movement pattern for Quadruped Hip Rotation. 2. Control the rotation in both directions—avoid using momentum. 3. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'bird_dog', 'Quadruped Hip Rotation', 'hip_thrust, lunge, squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('b450c8f3-0a0a-4dbd-9470-dd1009944c69', 'Weighted Seated Single Leg Knee Extension (Version 2)', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Weighted Seated Single Leg Knee Extension (versio is a extension exercise that primarily loads your quadriceps. Being seated provides stability, allowing you to focus on the working muscles. Leg training boosts metabolism and builds functional, real-world strength.', '105391201', '105391201-Weighted-Seated-Single-Leg-Knee-Extension-(VERSIO.mp4', 'male', FALSE, '2025-12-03 23:26:26.507873+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Extend your legs until straight, squeezing your quads at the top. 3. Lower with control back to the starting position. 4. Complete all reps on one side, then switch to the other side. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 67, 5, 7, FALSE, TRUE, 'leg_extension', 'Weighted Seated Single Leg Knee Extension (versio', 'squat, leg_press, lunge', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('b46bf243-b6cb-4c6d-b600-c6d4d9050d7a', 'Pull Apart (Band)', 'Shoulders', 'Resistance Band, Anchor Point', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'The Band Pull Apart is a pulling exercise that targets your delts for shoulder development. Bands are joint-friendly and portable, perfect for any training environment. Shoulder development enhances both performance and upper body aesthetics.', '81061201', '81061201-Band-Pull-Apart-(female)_Shoulders_.mp4', 'female', FALSE, '2025-12-03 23:26:30.887491+00', '1. Secure the resistance band appropriately for Band Pull Apart. 2. Set up in the starting position for Band Pull Apart. 3. Execute the movement with proper form, focusing on your delts. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 55, 7, 8, TRUE, TRUE, 'pull_apart', 'Pull Apart', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('b4965d18-2386-4230-92d8-bd8a8ad81fcb', 'Incline Bicep Curl - Inner (Dumbbell)', 'Arms', 'Dumbbells, Incline Bench', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'Build bigger biceps with this curling movement that targets the front of your arms. Your forearms work as secondary movers, adding to the training stimulus. Using an incline changes the angle of resistance for varied muscle recruitment. Using dumbbells requires more stabilization than barbell variations. Arm strength supports grip, pulling, and pushing in compound movements.', '3221201', '03221201-Dumbbell-Incline-Inner-Biceps-Curl_Upper-Arms-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:26.808474+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Incline Inner Biceps Curl. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Continue for your target rep count, maintaining good form throughout.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 95, 5, 7, FALSE, TRUE, 'bicep_curl', 'Incline Inner Biceps Curl', 'hammer_curl, preacher_curl, cable_curl', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('b499bdba-a5ce-4bbc-ae8d-179d06942e16', 'Bridge March', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'Build stronger glutes with this bridging movement focused on hip extension. The hamstrings assist throughout the movement, making this a well-rounded exercise. No equipment needed—your body provides all the resistance. Strong legs are the foundation for athletic performance and functional fitness.', '104141201', '104141201-Bridge-March-(VERSION-2)-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:24.698781+00', '1. Drive through your heels to lift your hips toward the ceiling. 2. Squeeze your glutes hard at the top of the movement. 3. Lower your hips back down with control. 4. Complete all reps with control before resting. Don''t rush—quality over quantity.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'marching', 'Bridge March', 'high_knees, butt_kicks, jumping_jack', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('b49a1b3f-b516-47e5-bede-8100b5abd710', 'Sumo Squat Floor Touch', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Inner Thighs","Hamstrings"}'::text[], 'The Sumo Squat Floor Touch is a squatting exercise that primarily loads your quadriceps. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. No equipment needed—your body provides all the resistance. Lower body strength improves everything from walking to heavy compound lifts.', '44171201', '44171201-Sumo-Squat-Floor-Touch_Hips.mp4', 'male', FALSE, '2025-12-03 23:26:20.392006+00', '1. Position yourself on the floor for Sumo Squat Floor Touch. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Repeat for the prescribed number of repetitions.', 'Squat', NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 80, 7, 8, TRUE, TRUE, 'squat', 'Sumo Squat Floor Touch', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('b49a28b0-cb9e-4b57-b808-a951c7692529', 'Backward Forward Turn To Side Neck Stretch', 'Neck', 'Bodyweight', '{"Neck"}'::text[], '{"Traps"}'::text[], 'The Backward Forward Turn To Side Neck Stretch provides a deep stretch for your neck, ideal for recovery and mobility work. Flexibility work like this enhances performance and prevents stiffness.', '55051201', '55051201-Backward-Forward-Turn-to-Side-Neck-Stretch_Neck_.mp4', 'male', FALSE, '2025-12-03 23:26:29.837118+00', '1. Move into the stretch position for Backward Forward Turn To Side Neck Stretch. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. 4. Switch sides and repeat for equal time.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'neck_stretch', 'Backward Forward Turn To Side Neck Stretch', 'stretch_hip, stretch_hamstring, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('b4a1fdae-6f8a-4b2f-94b7-c3e6f9187195', 'Forward Sideward Hop', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Calves"}'::text[], 'Elevate your training with this movement exercise that develops speed, power, and coordination. A versatile bodyweight movement perfect for home or gym training. Plyometric training builds explosive power that transfers to sports and daily activities. Maintain proper breathing - exhale during the effort phase.', '74941201', '74941201-Forward-Sideward-Hop-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:23.586683+00', '1. Set up in the starting position for Forward Sideward Hop. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'hop', 'Forward Sideward Hop', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('b4a44a5c-b73d-4674-8534-b05abe30f7d2', 'Bent Leg Superman Raise', 'Back', 'Bodyweight', '{"Lower Back"}'::text[], '{"Glutes","Upper Back"}'::text[], 'Build leg strength with this raising movement focusing on your lower back. Your glutes work as secondary movers, adding to the training stimulus. This bodyweight exercise requires no equipment and can be done anywhere. Strong legs are the foundation for athletic performance and functional fitness.', '96271201', '96271201-Bent-Leg-Superman-Raise-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:31.347577+00', '1. Set up in the starting position for Bent Leg Superman Raise. 2. Execute the movement with proper form, focusing on your lower back. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'back_extension', 'Bent Leg Superman Raise', 'crunch, plank, russian_twist, hanging_knee_raise', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('b4b26c36-d142-4ebd-8f4e-da574e337e4e', 'Crocodile Crawl', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Elevate your training with this movement exercise that develops speed, power, and coordination. No equipment needed—your body provides all the resistance. Great for improving athletic performance, burning calories, and building conditioning. Control the negative portion for maximum muscle engagement.', '75991201', '75991201-Crocodile-Crawl-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:26.507873+00', '1. Set up in the starting position for Crocodile Crawl. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Crocodile Crawl', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('b4b99268-12d4-4d5e-858d-f161916cf9ab', 'Seated Pull Back (Chair)', 'Back', 'Chair', '{"Upper Back"}'::text[], '{"Lats"}'::text[], 'Target your rhomboids and mid-traps with this pulling movement. Your lats work as secondary movers, adding to the training stimulus. Being seated provides stability, allowing you to focus on the working muscles. Back development is crucial for pulling strength and overall upper body function.', '91121201', '91121201-Sitting-Pull-Back-on-a-Chair-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:37.877283+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Continue for your target rep count, maintaining good form throughout. Exhale during the exertion phase of the movement. A solid choice for back day.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 35, 7, 8, TRUE, TRUE, 'back_exercise', 'Seated Pull Back On A Chair', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('b4c3fefb-5d9c-4988-84ea-6eab4b105d03', 'Neck Half Circle', 'Shoulders', 'Bodyweight', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'Strengthen your neck with this movement exercise for improved stability. No equipment needed—your body provides all the resistance. Include this exercise in your routine for balanced strength development. A staple exercise that belongs in most training programs.', '56911201', '56911201-Neck-Half-Circle-(female)_Neck_.mp4', 'female', FALSE, '2025-12-03 23:26:35.532804+00', '1. Set up in the starting position for Neck Half Circle. 2. Execute the movement with proper form, focusing on your delts. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'neck_exercise', 'Neck Half Circle', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('b4cf8795-3353-4b18-b05c-31d63737c13c', 'Rear Fly Stepback', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{"Quads"}'::text[], 'Build power and athleticism with this high-intensity flying exercise that challenges your entire body. You''ll also feel your quads working to support the movement. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '55311201', '55311201-Rear-Fly-Stepback_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:22.247914+00', '1. Set up a box or step platform at the appropriate height. 2. With a slight bend in your elbows, move the weight in a wide arc. 3. Squeeze your chest muscles at the center/top of the movement. 4. Return with control, feeling the stretch at the bottom. 5. Repeat for the prescribed number of repetitions. Focus on the mind-muscle connection.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'rear_delt', 'Rear Fly Stepback', 'bench_press, incline_bench_press, push_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
